ruleSearch.bookList:
@js:(function(){
var d=JSON.parse(result).data.list;var out=[];
for(var i=0;i<d.length;i++){
  var c=d[i];
  var id=c.comic_id&&c.comic_id!=='0'?c.comic_id:c.id;
  if(!id)continue;
  out.push({name:c.title||c.name,author:c.authors||'',coverUrl:c.cover,bookUrl:'https://v4api.zaimanhua.com/app/v1/comic/detail/'+id+'?channel=android',lastChapter:c.last_update_chapter_name||'',kind:c.types||'',intro:(c.description||c.last_name||c.last_update_chapter_name||'')});
}
return out;})()

ruleToc.chapterList:
@js:(function(){
var m=book.bookUrl.match(/comic\/detail\/(\d+)/);
var cid=m?m[1]:'';
var groups=$.data.data.chapters||[];
var out=[];
for(var g=0;g<groups.length;g++){
  var gtitle=groups[g].title||'默认';
  var list=groups[g].data||[];
  for(var i=list.length-1;i>=0;i--){
    var ch=list[i];
    var t=String(ch.chapter_title||'').replace(/^(?:连载版?)?(\d+\.?\d*)([话卷])?$/,function(a,n,t2){return '第'+n+(t2||'话');});
    out.push({name:'['+gtitle+'] '+t,url:'https://v4api.zaimanhua.com/app/v1/comic/chapter/'+cid+'/'+ch.chapter_id});
  }
}
return out;})()

ruleContent.content:
@js:(function(){
var d=JSON.parse(result).data.data;
var imgs=d.page_url_hd||d.page_url||[];
var out=[];
for(var i=0;i<imgs.length;i++){out.push('<img src="'+imgs[i]+'">');}
return out.join('\n');})()

